@once
@push('styles')
<style>
.admin-hero{position:relative;overflow:hidden;display:flex;flex-direction:column;gap:1.5rem;justify-content:space-between;border:1px solid #D6E6EA;border-radius:30px;background:linear-gradient(110deg,#DFF2EE,#EAF6F4,#E4EEF6);padding:2rem;box-shadow:0 20px 45px rgba(15,40,53,.08)}
@media(min-width:1024px){.admin-hero{flex-direction:row;align-items:center}}
.admin-eyebrow{font-size:.7rem;font-weight:800;letter-spacing:.24em;text-transform:uppercase;color:#1B5E6A}.admin-title{margin-top:.75rem;font-size:clamp(1.8rem,3vw,2.5rem);font-weight:900;color:#0A2334}.admin-description{margin-top:.75rem;max-width:42rem;font-size:.95rem;line-height:1.6;color:#3b5d6e}.admin-primary,.admin-secondary,.form-submit,.form-cancel{display:inline-flex;align-items:center;justify-content:center;border-radius:.75rem;padding:.75rem 1.25rem;font-size:.875rem;font-weight:800}.admin-primary,.form-submit{background:#8AFD5D;color:#001E30;box-shadow:0 10px 20px rgba(138,253,93,.2)}.admin-secondary,.form-cancel{border:1px solid #C7DCE2;background:#fff;color:#0A2334}.admin-success{border:1px solid #BFE6B1;border-radius:1rem;background:#EAFBF0;padding:1rem;color:#0E6B54;font-size:.875rem;font-weight:700}.admin-stat,.admin-panel{border:1px solid #D8E6EB;border-radius:26px;background:#F7FBFC;padding:1.25rem;box-shadow:0 12px 26px rgba(15,40,53,.06)}.admin-stat p{font-size:.875rem;color:#4b6473}.admin-stat strong{display:block;margin-top:1rem;font-size:1.8rem;font-weight:900;color:#0A2334}.admin-stat small{display:block;margin-top:.5rem;font-size:.75rem;color:#5F7785}.admin-heading{font-size:1.25rem;font-weight:800;color:#0A2334}.admin-empty{border:1px dashed #D8E6EB;border-radius:1rem;background:#fff;padding:2.5rem;text-align:center;font-size:.875rem;color:#5F7785}.admin-empty a{font-weight:800;color:#0E6B54}.admin-table-wrap{overflow-x:auto;border:1px solid #D8E6EB;border-radius:1rem}.admin-table{min-width:700px;width:100%;border-collapse:collapse}.admin-table th{background:#fff;padding:.85rem 1.25rem;text-align:left;font-size:.65rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:#5F7785}.admin-table td{padding:1rem 1.25rem;border-top:1px solid #EAF1F3;font-size:.875rem;color:#456073}.admin-table tbody tr:hover{background:#fff}.admin-table td b{color:#0A2334}.admin-avatar{display:inline-flex;width:2.25rem;height:2.25rem;align-items:center;justify-content:center;margin-right:.6rem;border-radius:.75rem;background:#D8F7CB;color:#0E6B54;font-weight:900}.admin-actions{display:flex;justify-content:flex-end;gap:.4rem}.admin-actions a,.admin-actions button{border:1px solid #D8E6EB;border-radius:.5rem;background:#fff;padding:.45rem .65rem;font-size:.7rem;font-weight:700;color:#0E6B54}.admin-actions button{border-color:#fecdd3;color:#e11d48}.form-label{display:block;margin-bottom:.5rem;color:#0A2334;font-size:.75rem;font-weight:800}.form-input{width:100%;border:1px solid #D8E6EB;border-radius:.75rem;background:#fff;padding:.75rem 1rem;font-size:.875rem;color:#0A2334;outline:none}.form-input:focus{border-color:#0E6B54;box-shadow:0 0 0 3px rgba(14,107,84,.12)}.form-error{margin-top:.25rem;font-size:.75rem;color:#e11d48}
</style>
@endpush
@endonce
